fn regex_matches(pattern: &str, text: &str) -> bool {
    match_at(pattern, text, 0).0
}

fn match_at(pattern: &str, text: &str, text_idx: usize) -> (bool, usize) {
    let p_chars: Vec<char> = pattern.chars().collect();
    let t_chars: Vec<char> = text.chars().collect();

    let mut p_idx = 0;
    let mut t_idx = text_idx;

    while p_idx < p_chars.len() {
        if p_idx + 1 < p_chars.len() && p_chars[p_idx + 1] == '+' {
            // One or more
            let ch = p_chars[p_idx];
            if t_idx >= t_chars.len() || !char_matches(ch, t_chars[t_idx]) {
                return (false, t_idx);
            }
            t_idx += 1;
            while t_idx < t_chars.len() && char_matches(ch, t_chars[t_idx]) {
                t_idx += 1;
            }
            p_idx += 2;
        } else if p_idx + 1 < p_chars.len() && p_chars[p_idx + 1] == '*' {
            // Zero or more
            let ch = p_chars[p_idx];
            while t_idx < t_chars.len() && char_matches(ch, t_chars[t_idx]) {
                t_idx += 1;
            }
            p_idx += 2;
        } else if p_idx + 1 < p_chars.len() && p_chars[p_idx + 1] == '?' {
            // Optional
            let ch = p_chars[p_idx];
            if t_idx < t_chars.len() && char_matches(ch, t_chars[t_idx]) {
                t_idx += 1;
            }
            p_idx += 2;
        } else {
            // Regular character
            if t_idx >= t_chars.len() || !char_matches(p_chars[p_idx], t_chars[t_idx]) {
                return (false, t_idx);
            }
            t_idx += 1;
            p_idx += 1;
        }
    }
    (true, t_idx)
}

fn char_matches(p: char, t: char) -> bool {
    p == '.' || p == t
}

