fn regex_matches(pattern: &str, text: &str) -> bool {
    // Try to match starting from any position
    for start in 0..=text.len() {
        if matches_at(pattern, text, start) {
            return true;
        }
    }
    false
}

fn matches_at(pattern: &str, text: &str, start: usize) -> bool {
    let mut p_pos = 0;
    let mut t_pos = start;

    let pattern_bytes = pattern.as_bytes();
    let text_bytes = text.as_bytes();

    while p_pos < pattern_bytes.len() {
        // Check for escape sequences like \d, \w, \s
        if p_pos + 1 < pattern_bytes.len() && pattern_bytes[p_pos] == b'\\' {
            let next = pattern_bytes[p_pos + 1];

            // Check for quantifier after escape
            let quantifier = if p_pos + 2 < pattern_bytes.len() {
                match pattern_bytes[p_pos + 2] {
                    b'+' => Some('+'),
                    b'*' => Some('*'),
                    b'?' => Some('?'),
                    b'{' => Some('{'),
                    _ => None,
                }
            } else {
                None
            };

            match (next, quantifier) {
                (b'd', Some('+')) => {
                    // \d+ pattern
                    if t_pos >= text_bytes.len() || !text_bytes[t_pos].is_ascii_digit() {
                        return false;
                    }
                    t_pos += 1;
                    while t_pos < text_bytes.len() && text_bytes[t_pos].is_ascii_digit() {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b'd', Some('*')) => {
                    // \d* pattern
                    while t_pos < text_bytes.len() && text_bytes[t_pos].is_ascii_digit() {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b'd', Some('?')) => {
                    // \d? pattern
                    if t_pos < text_bytes.len() && text_bytes[t_pos].is_ascii_digit() {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b'w', Some('+')) => {
                    // \w+ pattern
                    if t_pos >= text_bytes.len() || !is_word_char(text_bytes[t_pos]) {
                        return false;
                    }
                    t_pos += 1;
                    while t_pos < text_bytes.len() && is_word_char(text_bytes[t_pos]) {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b'w', Some('*')) => {
                    // \w* pattern
                    while t_pos < text_bytes.len() && is_word_char(text_bytes[t_pos]) {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b'w', Some('?')) => {
                    // \w? pattern
                    if t_pos < text_bytes.len() && is_word_char(text_bytes[t_pos]) {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b's', Some('+')) => {
                    // \s+ pattern
                    if t_pos >= text_bytes.len() || !is_whitespace_char(text_bytes[t_pos]) {
                        return false;
                    }
                    t_pos += 1;
                    while t_pos < text_bytes.len() && is_whitespace_char(text_bytes[t_pos]) {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b's', Some('*')) => {
                    // \s* pattern
                    while t_pos < text_bytes.len() && is_whitespace_char(text_bytes[t_pos]) {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b's', Some('?')) => {
                    // \s? pattern
                    if t_pos < text_bytes.len() && is_whitespace_char(text_bytes[t_pos]) {
                        t_pos += 1;
                    }
                    p_pos += 3;
                }
                (b'd', None) => {
                    // \d without quantifier
                    if t_pos >= text_bytes.len() || !text_bytes[t_pos].is_ascii_digit() {
                        return false;
                    }
                    t_pos += 1;
                    p_pos += 2;
                }
                (b'w', None) => {
                    // \w without quantifier
                    if t_pos >= text_bytes.len() || !is_word_char(text_bytes[t_pos]) {
                        return false;
                    }
                    t_pos += 1;
                    p_pos += 2;
                }
                (b's', None) => {
                    // \s without quantifier
                    if t_pos >= text_bytes.len() || !is_whitespace_char(text_bytes[t_pos]) {
                        return false;
                    }
                    t_pos += 1;
                    p_pos += 2;
                }
                (b'n', None) => {
                    // \n
                    if t_pos >= text_bytes.len() || text_bytes[t_pos] != b'\n' {
                        return false;
                    }
                    t_pos += 1;
                    p_pos += 2;
                }
                (c, None) => {
                    // Escaped character like \( or \)
                    if t_pos >= text_bytes.len() || text_bytes[t_pos] != c {
                        return false;
                    }
                    t_pos += 1;
                    p_pos += 2;
                }
                _ => return false,
            }
        } else {
            // Regular character or quantifier on previous character
            if t_pos >= text_bytes.len() || text_bytes[t_pos] != pattern_bytes[p_pos] {
                return false;
            }
            t_pos += 1;
            p_pos += 1;
        }
    }

    true
}

fn is_word_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_'
}

fn is_whitespace_char(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r'
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    String(String),
    Identifier(String),
    Semicolon,
    Of,
    To,
    LeftBrace,
    RightBrace,
    Match,
    Some,
    Any,
    Option,
}

struct Lexer {
    input: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        if self.pos < self.input.len() {
            Some(self.input[self.pos])
        } else {
            None
        }
    }

    fn next(&mut self) -> Option<char> {
        if self.pos < self.input.len() {
            let ch = self.input[self.pos];
            self.pos += 1;
            Some(ch)
        } else {
            None
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.peek() {
            if ch.is_whitespace() {
                self.next();
            } else {
                break;
            }
        }
    }

    fn read_string(&mut self) -> Result<String, String> {
        self.next(); // consume opening quote
        let mut result = String::new();
        while let Some(ch) = self.peek() {
            if ch == '"' {
                self.next();
                return Ok(result);
            } else if ch == '\\' {
                self.next();
                if let Some(escaped) = self.next() {
                    match escaped {
                        'n' => result.push('\n'),
                        't' => result.push('\t'),
                        'r' => result.push('\r'),
                        '\\' => result.push('\\'),
                        '"' => result.push('"'),
                        _ => {
                            result.push('\\');
                            result.push(escaped);
                        }
                    }
                }
            } else {
                result.push(ch);
                self.next();
            }
        }
        Err("Unterminated string".to_string())
    }

    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while let Some(ch) = self.peek() {
            if ch.is_alphanumeric() || ch == '_' {
                result.push(ch);
                self.next();
            } else {
                break;
            }
        }
        result
    }

    fn next_token(&mut self) -> Result<Option<Token>, String> {
        self.skip_whitespace();
        match self.peek() {
            None => Ok(None),
            Some(';') => {
                self.next();
                Ok(Some(Token::Semicolon))
            }
            Some('{') => {
                self.next();
                Ok(Some(Token::LeftBrace))
            }
            Some('}') => {
                self.next();
                Ok(Some(Token::RightBrace))
            }
            Some('<') => {
                // Check if this is a symbol like <word>
                let mut ident = String::new();
                self.next(); // consume <
                while let Some(ch) = self.peek() {
                    if ch == '>' {
                        self.next(); // consume >
                        return Ok(Some(Token::Identifier(ident)));
                    } else if ch.is_alphanumeric() {
                        ident.push(ch);
                        self.next();
                    } else {
                        break;
                    }
                }
                Err("Expected '>'".to_string())
            }
            Some('"') => {
                let s = self.read_string()?;
                Ok(Some(Token::String(s)))
            }
            Some(ch) if ch.is_alphabetic() => {
                let ident = self.read_identifier();
                let token = match ident.as_str() {
                    "of" => Token::Of,
                    "to" => Token::To,
                    "match" => Token::Match,
                    "some" => Token::Some,
                    "any" => Token::Any,
                    "option" => Token::Option,
                    _ => Token::Identifier(ident),
                };
                Ok(Some(token))
            }
            Some(ch) if ch.is_numeric() => {
                let mut num = String::new();
                while let Some(c) = self.peek() {
                    if c.is_numeric() {
                        num.push(c);
                        self.next();
                    } else {
                        break;
                    }
                }
                Ok(Some(Token::Identifier(num)))
            }
            Some(ch) => {
                Err(format!("Unexpected character: {}", ch))
            }
        }
    }
}

#[derive(Debug, Clone)]
enum Expression {
    Literal(String),
    Symbol(String),
    Quantified {
        expr: Box<Expression>,
        quantifier: Quantifier,
    },
    Group(Vec<Expression>),
    MatchGroup(Vec<Expression>),
}

#[derive(Debug, Clone)]
enum Quantifier {
    Exact(usize),
    Range(usize, usize),
    OneOrMore,
    ZeroOrMore,
    Optional,
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Result<Self, String> {
        let mut lexer = Lexer::new(input);
        let mut tokens = Vec::new();
        while let Some(token) = lexer.next_token()? {
            tokens.push(token);
        }
        Ok(Parser { tokens, pos: 0 })
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn next(&mut self) -> Option<Token> {
        if self.pos < self.tokens.len() {
            let token = self.tokens[self.pos].clone();
            self.pos += 1;
            Some(token)
        } else {
            None
        }
    }

    fn parse(&mut self) -> Result<Expression, String> {
        let mut expressions = Vec::new();
        while self.peek().is_some() {
            if let Token::Semicolon = self.peek().unwrap() {
                self.next();
                continue;
            }
            expressions.push(self.parse_expression()?);
            if let Some(Token::Semicolon) = self.peek() {
                self.next();
            }
        }

        if expressions.is_empty() {
            Err("Error:  --> 1:1\n  |\n1 | \n  | ^---\n  |\n  = expected root".to_string())
        } else if expressions.len() == 1 {
            Ok(expressions.into_iter().next().unwrap())
        } else {
            Ok(Expression::Group(expressions))
        }
    }

    fn parse_expression(&mut self) -> Result<Expression, String> {
        // Check for quantifier first
        if let Some(token) = self.peek() {
            match token {
                Token::Some => {
                    self.next();
                    if let Some(Token::Of) = self.peek() {
                        self.next();
                        let sub_expr = self.parse_atom()?;
                        return Ok(Expression::Quantified {
                            expr: Box::new(sub_expr),
                            quantifier: Quantifier::OneOrMore,
                        });
                    }
                }
                Token::Any => {
                    self.next();
                    if let Some(Token::Of) = self.peek() {
                        self.next();
                        let sub_expr = self.parse_atom()?;
                        return Ok(Expression::Quantified {
                            expr: Box::new(sub_expr),
                            quantifier: Quantifier::ZeroOrMore,
                        });
                    }
                }
                Token::Option => {
                    self.next();
                    if let Some(Token::Of) = self.peek() {
                        self.next();
                        let sub_expr = self.parse_atom()?;
                        return Ok(Expression::Quantified {
                            expr: Box::new(sub_expr),
                            quantifier: Quantifier::Optional,
                        });
                    }
                }
                Token::Identifier(s) if s.chars().all(|c| c.is_numeric()) => {
                    let num = s.parse::<usize>().map_err(|_| "Invalid number".to_string())?;
                    self.next();
                    if let Some(Token::Of) = self.peek() {
                        self.next();
                        let sub_expr = self.parse_atom()?;
                        return Ok(Expression::Quantified {
                            expr: Box::new(sub_expr),
                            quantifier: Quantifier::Exact(num),
                        });
                    } else if let Some(Token::To) = self.peek() {
                        self.next();
                        if let Some(Token::Identifier(s2)) = self.peek() {
                            if s2.chars().all(|c| c.is_numeric()) {
                                let num2 = s2.parse::<usize>().map_err(|_| "Invalid number".to_string())?;
                                self.next();
                                if let Some(Token::Of) = self.peek() {
                                    self.next();
                                    let sub_expr = self.parse_atom()?;
                                    return Ok(Expression::Quantified {
                                        expr: Box::new(sub_expr),
                                        quantifier: Quantifier::Range(num, num2),
                                    });
                                } else {
                                    return Err("Expected 'of'".to_string());
                                }
                            } else {
                                return Err("Expected number after 'to'".to_string());
                            }
                        } else {
                            return Err("Expected number after 'to'".to_string());
                        }
                    }
                }
                _ => {}
            }
        }

        self.parse_atom()
    }

    fn parse_atom(&mut self) -> Result<Expression, String> {
        match self.peek() {
            Some(Token::String(s)) => {
                let s = s.clone();
                self.next();
                Ok(Expression::Literal(s))
            }
            Some(Token::Identifier(s)) => {
                let s = s.clone();
                self.next();
                Ok(Expression::Symbol(s))
            }
            Some(Token::Match) => {
                self.next();
                if let Some(Token::LeftBrace) = self.peek() {
                    self.next();
                    let mut sub_expressions = Vec::new();
                    while let Some(token) = self.peek() {
                        if let Token::RightBrace = token {
                            self.next();
                            break;
                        }
                        if let Token::Semicolon = token {
                            self.next();
                            continue;
                        }
                        sub_expressions.push(self.parse_expression()?);
                    }
                    Ok(Expression::MatchGroup(sub_expressions))
                } else {
                    Err("Expected '{'".to_string())
                }
            }
            _ => Err("Expected expression".to_string()),
        }
    }
}

fn escape_regex_string(s: &str) -> String {
    let mut result = String::new();
    for ch in s.chars() {
        match ch {
            '\\' | '.' | '+' | '*' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '^' | '$' | '|'
            => {
                result.push('\\');
                result.push(ch);
            }
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            '\r' => result.push_str("\\r"),
            _ => result.push(ch),
        }
    }
    result
}

fn expr_to_regex(expr: &Expression) -> String {
    match expr {
        Expression::Literal(s) => escape_regex_string(s),
        Expression::Symbol(sym) => match sym.as_str() {
            "word" => "\\w".to_string(),
            "digit" => "\\d".to_string(),
            "space" => " ".to_string(),
            "whitespace" => "\\s".to_string(),
            "char" => ".".to_string(),
            _ => sym.clone(),
        },
        Expression::Quantified { expr, quantifier } => {
            let sub_regex = expr_to_regex(expr);
            let needs_group = matches!(expr.as_ref(), Expression::Literal(s) if s.len() > 1);

            let grouped = if needs_group {
                format!("(?:{})", sub_regex)
            } else {
                sub_regex
            };

            match quantifier {
                Quantifier::Exact(n) => format!("{}{{{}}}", grouped, n),
                Quantifier::Range(min, max) => format!("{}{{{},{}}}", grouped, min, max),
                Quantifier::OneOrMore => format!("{}+", grouped),
                Quantifier::ZeroOrMore => format!("{}*", grouped),
                Quantifier::Optional => format!("{}?", grouped),
            }
        }
        Expression::Group(exprs) => {
            let mut parts = Vec::new();
            for e in exprs {
                parts.push(expr_to_regex(e));
            }
            parts.join("")
        }
        Expression::MatchGroup(exprs) => {
            let mut parts = Vec::new();
            for e in exprs {
                parts.push(expr_to_regex(e));
            }
            let combined = parts.join("");
            format!("(?:{})", combined)
        }
    }
}

fn parse_melody(input: &str) -> Result<String, String> {
    let mut parser = Parser::new(input)?;
    let expr = parser.parse()?;
    Ok(expr_to_regex(&expr))
}
