                    test_string = Some(test.clone());
                }
            }
            "-f" | "--test-file" => {
                if let Some(path) = args_iter.next() {
                    test_file = Some(PathBuf::from(path));
                }
            }
            arg if !arg.starts_with('-') => {
                input_file_path = Some(arg.to_string());
            }
            _ => {}
        }
    }

    // Handle REPL mode
    if repl {
        eprintln!("Error: repl argument supplied with piped input or output");
        std::process::exit(1);
    }

    // Handle completions generation
    if let Some(_shell) = generate_completions {
        eprintln!("Completions not yet implemented");
        std::process::exit(1);
    }

    // Read input
    let input = if let Some(file_path) = &input_file_path {
        if file_path == "-" {
            let mut buffer = String::new();
            io::stdin().read_to_string(&mut buffer).expect("Failed to read stdin");
            buffer
        } else {
            fs::read_to_string(file_path).expect("Failed to read file")
        }
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer).expect("Failed to read stdin");
        buffer
    };

    // Parse and compile melody
    match parse_melody(&input) {
        Ok(regex_string) => {
            // Test if requested
            if let Some(test_str) = &test_string {
                if regex_matches(&regex_string, test_str) {
                    println!("'{}' matched", test_str);
                } else {
                    println!("'{}' did not match", test_str);
                }
            } else if let Some(test_file_path) = &test_file {
                let file_content = fs::read_to_string(test_file_path).expect("Failed to read test file");
                if regex_matches(&regex_string, &file_content) {
                    println!("{} matched", test_file_path.display());
                } else {
                    println!("{} did not match", test_file_path.display());
                }
            } else {
                // Output result
                if let Some(output_path) = output_path {
                    fs::write(output_path, &regex_string).expect("Failed to write output file");
                } else {
                    println!("{}", regex_string);
                }
            }
        }
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(65);
        }
    }
}

